/// Parallel Lives doubles token creation.
#[test]
fn parallel_lives_doubles_tokens() {
    let reg = registry();
    let mut state = game_at_step(Step::PrecombatMain, P0);

    // Put Parallel Lives on the battlefield.
    let _pl = named_creature(&mut state, &reg, "Parallel Lives", P0);

    // Create one token.
    state.create_token(
        "Spirit", P0, 1, 1,
        vec![Color::White],
        vec![CardType::Creature],
        vec![Keyword::Flying],
    );

    // Should have 2 tokens (1 + 1 extra from Parallel Lives).
    let spirits: Vec<_> = state.objects.values()
        .filter(|o| o.zone == Zone::Battlefield && o.is_token && o.name == "Spirit" && o.controller == P0)
        .collect();
    assert_eq!(spirits.len(), 2, "Parallel Lives should double tokens");
}

